const GLOSSARY_TERMS = [{"cat":"basics","term":{"en":"Diversification","hi":"विविधीकरण"},"def":{"en":"Spreading money across different investments to reduce the damage from any one of them.","hi":"किसी एक निवेश के नुकसान का असर घटाने के लिए पैसा अलग-अलग निवेशों में बाँटना।"}},{"cat":"basics","term":{"en":"Asset allocation","hi":"एसेट एलोकेशन"},"def":{"en":"How you split money among asset classes such as equity, debt, gold and cash, based on goals and risk.","hi":"लक्ष्य और जोखिम के आधार पर पैसे को इक्विटी, डेट, सोना और नकद जैसी एसेट श्रेणियों में बाँटना।"}},{"cat":"basics","term":{"en":"Compounding","hi":"कंपाउंडिंग (चक्रवृद्धि)"},"def":{"en":"Returns that earn their own returns over time, so growth accelerates.","hi":"ऐसा रिटर्न जो समय के साथ अपना भी रिटर्न कमाता है, इसलिए वृद्धि तेज़ होती है।"}},{"cat":"basics","term":{"en":"Inflation","hi":"महँगाई (इन्फ़्लेशन)"},"def":{"en":"The general rise in prices over time, which reduces what your money can buy.","hi":"समय के साथ सामान्य कीमतों में वृद्धि, जो आपके पैसे की क्रय शक्ति घटाती है।"}},{"cat":"funds","term":{"en":"SIP","hi":"SIP"},"def":{"en":"Systematic Investment Plan: investing a fixed amount at regular intervals into a fund.","hi":"Systematic Investment Plan: किसी फंड में नियमित अंतराल पर तय राशि निवेश करना।"}},{"cat":"basics","term":{"en":"Emergency fund","hi":"इमरजेंसी फ़ंड"},"def":{"en":"Cash or very safe, liquid savings to cover 3 to 6 months of expenses. Keep it separate from investments.","hi":"3 से 6 महीने के खर्च के लिए नकद या बहुत सुरक्षित, तुरंत उपलब्ध बचत। इसे निवेश से अलग रखें।"}},{"cat":"basics","term":{"en":"Net worth","hi":"नेट वर्थ"},"def":{"en":"Everything you own minus everything you owe. The best single measure of your financial progress.","hi":"आपकी सारी संपत्ति में से सारी देनदारी घटाकर बची राशि। वित्तीय प्रगति का सबसे अच्छा एकल पैमाना।"}},{"cat":"basics","term":{"en":"Term insurance","hi":"टर्म इंश्योरेंस"},"def":{"en":"Pure life cover that pays a large sum to your family if you die during the policy term, with no return if you survive.","hi":"शुद्ध जीवन बीमा, जो पॉलिसी अवधि में मृत्यु होने पर परिवार को बड़ी राशि देता है; जीवित रहने पर कोई रिटर्न नहीं।"}},{"cat":"basics","term":{"en":"Health insurance","hi":"हेल्थ इंश्योरेंस"},"def":{"en":"A policy that pays hospital and treatment costs up to the sum insured, subject to its waiting periods and limits.","hi":"बीमा राशि तक अस्पताल और इलाज का ख़र्च देने वाली पॉलिसी, उसके वेटिंग पीरियड और सीमाओं के अधीन।"}},{"cat":"basics","term":{"en":"EMI","hi":"EMI (मासिक किस्त)"},"def":{"en":"Equated monthly instalment: the fixed monthly amount that repays a loan, made up of interest and principal.","hi":"समान मासिक किस्त: लोन चुकाने की तय मासिक राशि, जिसमें ब्याज और मूलधन दोनों होते हैं।"}},{"cat":"basics","term":{"en":"Credit score","hi":"क्रेडिट स्कोर"},"def":{"en":"A number from 300 to 900, from bureaus such as CIBIL, that shows lenders how reliably you repay. Above 750 is generally good.","hi":"CIBIL जैसे ब्यूरो का 300 से 900 का अंक, जो क़र्ज़दाताओं को बताता है कि आप कितने भरोसे से चुकाते हैं। 750 से ऊपर आमतौर पर अच्छा।"}},{"cat":"india","term":{"en":"PPF","hi":"PPF (पब्लिक प्रोविडेंट फ़ंड)"},"def":{"en":"Public Provident Fund: a government-backed savings scheme with a 15-year lock-in and an interest rate set each quarter.","hi":"पब्लिक प्रोविडेंट फ़ंड: 15 साल के लॉक-इन वाली सरकारी समर्थन की बचत योजना, जिसकी ब्याज दर हर तिमाही तय होती है।"}},{"cat":"india","term":{"en":"EPF","hi":"EPF (कर्मचारी भविष्य निधि)"},"def":{"en":"Employees' Provident Fund: retirement savings for salaried employees, with contributions from both employee and employer.","hi":"कर्मचारी भविष्य निधि: वेतनभोगियों की रिटायरमेंट बचत, जिसमें कर्मचारी और नियोक्ता दोनों का योगदान होता है।"}},{"cat":"india","term":{"en":"NPS","hi":"NPS (नेशनल पेंशन सिस्टम)"},"def":{"en":"National Pension System: a low-cost, market-linked retirement scheme, with most of the money locked until age 60.","hi":"नेशनल पेंशन सिस्टम: कम लागत की बाज़ार-आधारित रिटायरमेंट योजना, जिसका ज़्यादातर पैसा 60 की उम्र तक बंद रहता है।"}}];
